begin;
create function pg_temp.check(b boolean,label text) returns text language plpgsql as $$ begin if b is distinct from true then raise exception 'S1_UPGRADE_ASSERTION: %',label; end if; return 'ok - '||label; end; $$;
select pg_temp.check((select privacy_settings from public.profile_private where id='81000001-0000-4000-8000-000000000001')='{"birthdate":"private","gender":"private","bio":"public","bank_account":"public","origin":"private"}'::jsonb,'alias conflicts fail closed and standalone public preserved');
select pg_temp.check(not exists(select 1 from public.profile_food_preferences),'legacy taste-game answers create no new food rows');
select pg_temp.check(not exists(select 1 from public.profile_private where tastes<>'{}'),'legacy tastes erased');
select pg_temp.check((select personal_data from public.profile_private where id='81000001-0000-4000-8000-000000000001')='{"gender":"female","bio":"Synthetic bio"}'::jsonb,'gender bio kept and health structure removed');
select pg_temp.check(not exists(select 1 from public.participants where personal_data<>'{}' or start_location_name is not null or start_latitude is not null or start_longitude is not null),'participant private copies removed');
select pg_temp.check((select payment_disclosure_source='legacy_linked_request' and payment_disclosure_requested_at is null from public.dutch_pay_bills where id='83000001-0000-4000-8000-000000000001'),'verified linked legacy snapshot has no invented consent time');
select pg_temp.check((select payment_disclosure_closed_at is not null and bank_name='' and account_number='' and account_holder='' from public.dutch_pay_bills where id='83000002-0000-4000-8000-000000000002'),'completed legacy bill erased');
select pg_temp.check(not exists(select 1 from public.notifications where bank_name<>'' or account_number<>''),'all notification account copies erased');
select pg_temp.check((select status='declined' from public.profile_consent_states where profile_id='81000001-0000-4000-8000-000000000001' and kind='marketing'),'latest timestamp and id determine legacy marketing decline');
select pg_temp.check((select granted_at=timestamptz '2024-02-29T01:02:03Z' and next_confirmation_at=timestamptz '2026-02-28T01:02:03Z' from public.profile_consent_states where profile_id='81000002-0000-4000-8000-000000000002' and kind='marketing'),'legacy marketing two calendar years retained');
select pg_temp.check(not exists(select 1 from public.profile_consent_states where kind='health') and not exists(select 1 from public.profile_health_preferences),'health never inferred from legacy');
select pg_temp.check((select count(*) from public.profile_consents where source='legacy')=7 and not exists(select 1 from public.profile_consents where source<>'legacy'),'old agreement events preserved without new approval');
grant execute on function pg_temp.check(boolean,text) to authenticated;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"81000001-0000-4000-8000-000000000001","role":"authenticated"}',true);
select pg_temp.check(not private.has_current_terms_consent(),'old service privacy approvals do not accept S1');
select pg_temp.check((select count(*) from public.public_profiles)=0,'upgraded pending JWT cannot read identity');
reset role;
rollback;
